CREATE TABLE production.part_prices(
    part_id int,
    valid_from date,
    price decimal(18,4) not null,
    PRIMARY KEY(part_id, valid_from)
);

CREATE TABLE #Events (
    event_id INT NOT NULL,
    happened_at DATETIME2 NOT NULL,
    note NVARCHAR(200)
);

